const PROJECTS=[{"name": "夕拾", "html": "<div class=\"experience-row recruiter-card\"><div class=\"entry-heading\"><h3>Windows 桌面日程工具</h3><p class=\"entry-role\">个人项目 · <strong class=\"project-signal\">产品设计、AI 辅助开发与用户运营</strong></p></div><div class=\"entry-point\"><h4>产品设计与交付</h4><p>围绕桌面随时查看与处理日程的需求，设计透明看板、日/周/月视图和收缩待办卡片，支持拖动创建时间段、跨天安排、提前提醒及本地备份，完成 <strong class=\"project-signal\">Windows 桌面产品交付</strong>。</p></div><div class=\"entry-point\"><h4>用户反馈与版本迭代</h4><p>累计积累<strong class=\"project-signal\">近百名用户</strong>，根据用户需求完成<strong class=\"project-signal\">最近两个版本迭代</strong>，持续完善日程安排与交互体验，将使用反馈落实为功能调整和版本更新。</p></div><div class=\"entry-point\"><h4>产品传播与方法沉淀</h4><p>结合自媒体平台开展产品介绍与传播，协助账号新增100 余名粉丝；将桌面封装、版本管理及故障排查沉淀为<strong class=\"project-signal\">可复用打包 Skill</strong>。</p></div><a class=\"project-link\" href=\"https://github.com/chouzing77/xishi\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub · 查看项目 <span aria-hidden=\"true\">↗</span><span class=\"sr-only\">（在新标签页打开）</span></a></div>"}, {"name": "小裁神", "html": "<div class=\"experience-row recruiter-card\"><div class=\"entry-heading\"><h3>劳动权益决策辅助 Web 产品</h3><p class=\"entry-role\">个人项目 · <strong class=\"project-signal\">独立产品设计</strong>、AI 辅助开发与内容传播</p></div><div class=\"entry-point\"><h4>需求定义与产品实现</h4><p>针对劳动者被约谈、劝退或要求签字时信息分散、行动顺序不清的问题，将专业知识转化为分步决策辅助工具，完成<strong class=\"project-signal\">需求拆解、产品设计、Web 实现与公开发布</strong>。</p></div><div class=\"entry-point\"><h4>核心功能与交互设计</h4><p>设计现状问卷、HR 谈判模拟、工资与补偿测算、证据任务及行动报告，组织<strong class=\"project-signal\">24 道情形问卷</strong>、<strong class=\"project-signal\">26 项证据任务</strong>，支持浏览器本地进度保存及报告导出。</p></div><div class=\"entry-point\"><h4>公开发布与内容传播</h4><p>通过 GitHub Pages 发布 v1.0，并在小红书、B 站等新媒体平台开展宣传，累计获得<strong class=\"project-signal\">近 2,500 次内容播放</strong>。</p></div><a class=\"project-link\" href=\"https://github.com/chouzing77/xiaocaishen\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub · 查看项目 <span aria-hidden=\"true\">↗</span><span class=\"sr-only\">（在新标签页打开）</span></a></div>"}, {"name": "Personal Learning Coach", "html": "<div class=\"experience-row recruiter-card\"><div class=\"entry-heading\"><h3>自适应学习教练 Skill</h3><p class=\"entry-role\">个人项目 · <strong class=\"project-signal\">AI 教学工作流设计</strong>、开源发布与内容实践</p></div><div class=\"entry-point\"><h4>教学流程设计</h4><p>针对 AI 学习中“看懂解释后仍难以独立应用”的问题，设计目标诊断、能力阶梯、主动练习、逐题考核、纠错、间隔复习和项目迁移的持续教学流程。</p></div><div class=\"entry-point\"><h4>学习档案与开源交付</h4><p>以 Markdown 保存学习档案，区分独立完成、提示后完成与待复测，<strong class=\"project-signal\">根据学习表现调整任务难度</strong>；完成<strong class=\"project-signal\">正式 Skill、方法模块及使用示例并开源发布</strong>。</p></div><div class=\"entry-point\"><h4>实践应用与内容传播</h4><p>在英语、公考及 AI 产品学习中持续应用，并将“AI 教考公”的实际使用过程制作成视频，全平台累计获得<strong class=\"project-signal\">近 1,000 次点击</strong>。</p></div><a class=\"project-link\" href=\"https://github.com/chouzing77/personal-learning-coach\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub · 查看项目 <span aria-hidden=\"true\">↗</span><span class=\"sr-only\">（在新标签页打开）</span></a></div>"}, {"name": "轻剪", "html": "<div class=\"experience-row recruiter-card\"><div class=\"entry-heading\"><h3>本机视频剪辑与 AI 创作工具</h3><p class=\"entry-role\">个人项目 · 需求定义、产品设计与 AI 辅助开发</p></div><div class=\"entry-point\"><h4>需求洞察与流程设计</h4><p>从个人使用中遇到的基础剪辑功能收费、切换软件后操作不适应等问题出发，自行制作所需工具，设计素材导入、时间轴剪辑、字幕编辑、草稿保存与成片导出的完整流程。</p></div><div class=\"entry-point\"><h4>本机 AI 与剪辑辅助</h4><p>集成 <strong class=\"project-signal\">Whisper 本机字幕识别</strong>、<strong class=\"project-signal\">Qwen 创作文案</strong>，并结合音量停顿与字幕重复分析生成删减建议，支持人工试听、修正及撤销，保留用户对最终成片的控制。</p></div><div class=\"entry-point\"><h4>多端交付与质量验证</h4><p>使用 Electron 与 FFmpeg 交付 <strong class=\"project-signal\">Web 和 Windows 1.1.0 版本</strong>，支持多格式导出及本地草稿恢复；公开源码、构建说明与测试，<strong class=\"project-signal\">9 组现有测试通过</strong>，已知问题在仓库中说明。</p></div><a class=\"project-link\" href=\"https://github.com/chouzing77/qingjian\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub · 查看项目 <span aria-hidden=\"true\">↗</span><span class=\"sr-only\">（在新标签页打开）</span></a></div>"}, {"name": "贴贴", "html": "<div class=\"experience-row recruiter-card\"><div class=\"entry-heading\"><h3>记录型贴纸软件</h3><p class=\"entry-role\">个人项目 · 产品设计、离线 AI 集成与移动端交付</p></div><div class=\"entry-point\"><h4>生活场景与产品设计</h4><p>围绕“把生活照片变成贴纸，按日期记录和回顾”的需求，设计拍照/导入、自动抠图、人工修正、贴纸日历、收藏、统计和每周回顾流程。</p></div><div class=\"entry-point\"><h4>离线 AI 与个人表达</h4><p>集成<strong class=\"project-signal\">本机主体分割和图片分类模型</strong>，生成贴纸及中文名称建议；提供手动圈选、边缘校正、描边样式和名称修改，将自动处理与个人表达结合。</p></div><div class=\"entry-point\"><h4>移动端交付与开源实践</h4><p>将 Web 产品封装为 <strong class=\"project-signal\">Android 1.8.3 内测版</strong>，实现<strong class=\"project-signal\">桌面组件、隐私分区与备份迁移</strong>；公开 Web 与 Android 源码，<strong class=\"project-signal\">公开版 103 项自检通过</strong>，原内测身份配置与模型权重未随仓库分发。</p></div><a class=\"project-link\" href=\"https://github.com/chouzing77/tietie\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub · 查看项目 <span aria-hidden=\"true\">↗</span><span class=\"sr-only\">（在新标签页打开）</span></a></div>"}];
const $=s=>document.querySelector(s),screen=$('#screen'),world=$('#world'),player=$('#player'),sprite=player.querySelector('img'),dialog=$('#project-dialog');
const WIDTH=4200,FLOOR=390;
const blocks=[
 // 01: four narrow steps with higher rises.
 {x:230,y:330,w:65,h:60},{x:350,y:265,w:65,h:125},{x:480,y:200,w:60,h:190},{x:610,y:150,w:75,h:240},
 // 02: separated narrow stepping stones, with safe ground below.
 {x:900,y:325,w:75,h:65},{x:1060,y:245,w:48,h:145},{x:1220,y:300,w:85,h:90},{x:1375,y:205,w:60,h:185},
 // 03: two tall steps lead to a launch deck and an apex star.
 {x:1590,y:325,w:100,h:65},{x:1710,y:260,w:170,h:130},
 // 04: climb to a pressure plate; both chamber doors unlock together.
 {x:2310,y:350,w:90,h:40},{x:2420,y:305,w:130,h:85},
 {x:2700,y:185,w:260,h:22},
 // 05: a floating bridge, then a higher final ledge.
 {x:3210,y:335,w:90,h:55},{x:3350,y:280,w:90,h:22},
 {x:3510,y:225,w:90,h:165},{x:3670,y:165,w:140,h:22}
];
const doors=[{x:2700,y:207,w:20,h:183},{x:2940,y:207,w:20,h:183}];
const plate={x:2460,y:305,w:52};let gateOpen=false;
const stars=[{x:630,y:70},{x:1390,y:125},{x:1770,y:10},{x:2810,y:310},{x:3720,y:88}].map(s=>({...s,found:false}));
function solids(){return gateOpen?blocks:blocks.concat(doors);}
function setGate(open){gateOpen=open;$('#gate-scene').classList.toggle('open',open);$('#gate-state').textContent=open?'OPEN':'LOCKED';}
let x=65,y=310,vy=0,facing=1,started=false,paused=false,last=0,walk=false,grounded=true;
const held=new Set(),reduce=matchMedia('(prefers-reduced-motion: reduce)');
const motivations={
 230:'我是J人',
 350:'想要一款透明不挡着我看桌面的日程工具',
 480:'为啥这样的小工具要收我钱！',
 610:'want it？do it！',
 900:'公司发疯无故裁员？',
 1060:'法科生不是好欺负的！',
 1220:'如果这件事不止我一个人遇到呢？',
 1375:'大庇天下寒士！',
 1590:'我加上AI',
 1710:'是不是等于无障碍学世上万物？',
 2310:'杀千刀的剪映',
 2420:'加个字幕要收钱？那我自己来！',
 3210:'我是有小猫的人',
 3510:'我要用贴纸记录我的小猫！'
};
// Audio is synthesized locally and unlocked only by a player gesture.
let audioContext=null,audioMaster=null,muted=false;
function unlockAudio(){
 try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
 if(!audioContext){audioContext=new Audio();audioMaster=audioContext.createGain();audioMaster.gain.value=muted?0:0.16;audioMaster.connect(audioContext.destination);}
 if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});
 }catch{/* Sound must never interrupt gameplay. */}
}
function sound(kind){
 if(muted||!audioContext||audioContext.state!=='running')return;
 const notes=kind==='star'?[[784,0,.12],[988,.09,.14],[1175,.19,.17],[1568,.32,.3]]:
 kind==='complete'?[[784,0,.13],[988,.1,.13],[1175,.2,.13],[1568,.3,.17],[1976,.45,.35]]:
 kind==='candy'?[[880,0,.09],[1320,.07,.16]]:
 kind==='gate'?[[330,0,.12],[440,.1,.12],[660,.2,.23]]:[[260,0,.13]];
 try{for(const [freq,delay,duration] of notes){const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=audioContext.currentTime+delay;
 osc.type=kind==='jump'?'square':'triangle';osc.frequency.setValueAtTime(freq,t);if(kind==='jump')osc.frequency.exponentialRampToValueAtTime(620,t+duration);
 gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(kind==='jump'?.22:.55,t+.008);gain.gain.exponentialRampToValueAtTime(.001,t+duration);
 osc.connect(gain);gain.connect(audioMaster);osc.start(t);osc.stop(t+duration+.02);osc.onended=()=>{osc.disconnect();gain.disconnect();};
 }}catch{/* Optional audio fallback. */}
}
$('#sound').onclick=()=>{muted=!muted;unlockAudio();if(audioMaster)audioMaster.gain.setValueAtTime(muted?0:.16,audioContext.currentTime);$('#sound').textContent=muted?'音效：关':'音效：开';$('#sound').setAttribute('aria-pressed',String(muted));$('#sound').setAttribute('aria-label',muted?'开启音效':'关闭音效');if(started)screen.focus({preventScroll:true});};
const candies=blocks.filter(b=>motivations[b.x]).map(b=>({x:b.x+b.w/2-8,y:b.y-27,text:motivations[b.x],project:b.x<850?0:b.x<1500?1:b.x<2200?2:b.x<3100?3:4,found:false}));
$('#blocks').innerHTML=blocks.map(b=>`<div class="block" style="left:${b.x}px;top:${b.y}px;width:${b.w}px;height:${b.h}px"></div>`).join('');
$('#candies').innerHTML=candies.map((c,i)=>`<div id="candy-${i}" class="candy candy-${c.project}" style="left:${c.x}px;top:${c.y}px" aria-hidden="true"></div>`).join('');
function noteCollection(){const found=candies.filter(c=>c.found);$('#notes').hidden=!found.length;$('#note-list').innerHTML=candies.map((c,i)=>c.found?`<button data-note="${i}">${PROJECTS[c.project].name} · 纸条 ${candies.slice(0,i+1).filter(n=>n.project===c.project).length}</button>`:'').join('');$('#note-list').querySelectorAll('button').forEach(b=>b.onclick=()=>openNote(+b.dataset.note));}
function openNote(i){const c=candies[i];if(!c?.found||dialog.open)return;held.clear();dialog.classList.add('paper-note');$('#close-dialog').setAttribute('aria-label','关闭小纸条');dialog.querySelector('.dialog-kicker').textContent='捡到一张小纸条';$('#project-name').textContent=PROJECTS[c.project].name;$('#project-body').innerHTML='<p class="note-message"></p>';$('#project-body').querySelector('p').textContent=c.text;dialog.showModal();$('#state').textContent='发现小纸条';}
$('#blocks').insertAdjacentHTML('beforeend',`<div id="gate-scene"><div class="wire" style="left:2486px;top:306px;width:224px;height:82px"></div><div class="pressure-plate" style="left:${plate.x}px;top:${plate.y-9}px;width:${plate.w}px"></div>${doors.map(b=>`<div class="gate-door" style="left:${b.x}px;top:${b.y}px;width:${b.w}px;height:${b.h}px"></div>`).join('')}<div id="gate-state" style="left:2770px;top:211px">LOCKED</div></div>`);
$('#stars').innerHTML=stars.map((s,i)=>`<div class="star" id="star-${i}" style="left:${s.x}px;top:${s.y}px" aria-hidden="true">★</div>`).join('');
function collection(){const n=stars.filter(s=>s.found).length;$('#count').textContent=n;$('#progress').textContent=n===5?'五颗星已点亮。我的闪光点，是把好奇心变成真实作品。':`已发现 ${n} / 5 个项目，跳上平台，触碰星星解锁。`;$('#collection-list').innerHTML=stars.map((s,i)=>`<button data-project="${i}" ${s.found?'':'disabled'}>${s.found?'★ '+PROJECTS[i].name:'☆ 未发现 '+(i+1)}</button>`).join('');$('#collection-list').querySelectorAll('button').forEach(b=>b.onclick=()=>openProject(+b.dataset.project));}
function openProject(i){if(!stars[i]?.found||dialog.open)return;held.clear();dialog.classList.remove('paper-note');$('#close-dialog').setAttribute('aria-label','关闭项目介绍');dialog.querySelector('.dialog-kicker').textContent='STAR DISCOVERED / 项目档案';$('#project-name').textContent=PROJECTS[i].name;$('#project-body').innerHTML=PROJECTS[i].html;dialog.showModal();$('#state').textContent='项目档案';}
function closeProject(){dialog.close();held.clear();$('#state').textContent=paused?'已暂停':'向右探索 →';screen.focus({preventScroll:true});}
$('#close-dialog').onclick=$('#continue').onclick=closeProject;dialog.addEventListener('cancel',e=>{e.preventDefault();closeProject();});
function jump(){if(started&&!paused&&!dialog.open&&grounded){vy=-575;grounded=false;sound('jump');}}
function inspect(){const i=stars.findIndex(s=>s.found&&Math.abs(s.x-x)<130);if(i>=0)openProject(i);else $('#state').textContent='跳上平台，触碰 ★';}
function action(a){unlockAudio();if(a==='jump')jump();if(a==='down')inspect();}
function setPaused(value){paused=value;held.clear();$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').ariaLabel=paused?'继续游戏':'暂停游戏';$('#state').textContent=paused?'已暂停':'向右探索 →';}
$('#pause').onclick=()=>{if(started){setPaused(!paused);screen.focus({preventScroll:true});}};
$('#start').onclick=()=>{unlockAudio();started=true;$('#start-panel').hidden=true;setPaused(false);screen.focus({preventScroll:true});};
$('#reset').onclick=()=>{x=65;y=310;vy=0;grounded=true;setGate(false);candies.forEach((c,i)=>{c.found=false;$('#candy-'+i).hidden=false;});noteCollection();stars.forEach((s,i)=>{s.found=false;$('#star-'+i).classList.remove('found');});collection();setPaused(false);if(started)screen.focus({preventScroll:true});};
const keys={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'jump',' ':'jump',ArrowDown:'down'};
window.addEventListener('keydown',e=>{if(dialog.open||!started)return;if(!screen.contains(document.activeElement)&&document.activeElement!==screen)return;if(e.key==='Escape'){setPaused(!paused);return;}const a=keys[e.key];if(!a)return;e.preventDefault();if(!e.repeat)action(a);if(!paused)held.add(a);});
window.addEventListener('keyup',e=>held.delete(keys[e.key]));window.addEventListener('blur',()=>{if(started)setPaused(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started)setPaused(true);});
document.querySelectorAll('[data-action]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(!started||paused||dialog.open)return;held.add(b.dataset.action);action(b.dataset.action);screen.focus({preventScroll:true});});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>held.delete(b.dataset.action));b.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!e.repeat)action(b.dataset.action);if(started&&!paused)held.add(b.dataset.action);}});b.addEventListener('keyup',()=>held.delete(b.dataset.action));b.addEventListener('blur',()=>held.delete(b.dataset.action));});
function render(){const zoom=screen.clientWidth<500?1.3:1.5;const viewW=screen.clientWidth/zoom,viewH=screen.clientHeight/zoom;const camera=Math.max(0,Math.min(Math.max(0,WIDTH-viewW),x-viewW*.37));const cameraY=Math.max(0,Math.min(Math.max(0,440-viewH),y+40-viewH*.56));world.style.transform=`scale(${zoom}) translate(${-camera}px,${-cameraY}px)`;player.style.transform=`translate(${x}px,${y}px) scaleX(${facing})`;const moving=started&&!paused&&!dialog.open&&(held.has('left')||held.has('right'))&&grounded&&!reduce.matches;const source=!grounded?'jump-4.png':moving?'walk.gif':'still.png';if(sprite.getAttribute('src')!=='assets/cyber-'+source)sprite.src='assets/cyber-'+source;}
function step(dt){
 const dx=(held.has('right')?1:0)-(held.has('left')?1:0);if(dx)facing=dx;
 const oldX=x;x=Math.max(0,Math.min(WIDTH-66,x+dx*205*dt));
 for(const b of solids()){if(y+80>b.y+.01&&y<b.y+b.h&&x+52>b.x&&x+14<b.x+b.w){if(dx>0&&oldX+52<=b.x+.01)x=b.x-52;else if(dx<0&&oldX+14>=b.x+b.w-.01)x=b.x+b.w-14;}}
 const oldY=y;vy+=1300*dt;y+=vy*dt;grounded=false;
 for(const b of solids()){if(x+52>b.x&&x+14<b.x+b.w){if(vy>=0&&oldY+80<=b.y+.01&&y+80>=b.y){y=b.y-80;vy=0;grounded=true;}else if(vy<0&&oldY>=b.y+b.h-.01&&y<=b.y+b.h){y=b.y+b.h;vy=0;}}}
 if(y+80>=FLOOR){y=FLOOR-80;vy=0;grounded=true;}
 if(!gateOpen&&grounded&&Math.abs(y+80-plate.y)<1&&x+52>plate.x&&x+14<plate.x+plate.w){setGate(true);sound('gate');$('#state').textContent='星门已打开 →';}
 for(let i=0;i<candies.length;i++){const c=candies[i];if(!c.found&&x+52>c.x&&x+14<c.x+16&&y<c.y+20&&y+80>c.y){c.found=true;$('#candy-'+i).hidden=true;noteCollection();sound('candy');openNote(i);return;}}
 for(let i=0;i<stars.length;i++){const s=stars[i];if((i!==3||gateOpen)&&!s.found&&x+52>s.x&&x+14<s.x+48&&y<s.y+48&&y+80>s.y){s.found=true;$('#star-'+i).classList.add('found');collection();sound(stars.every(star=>star.found)?'complete':'star');openProject(i);break;}}
}
function tick(t){const dt=Math.min((t-last)/1000||0,.025);last=t;if(started&&!paused&&!dialog.open){let remaining=dt;while(remaining>0&&!dialog.open){const slice=Math.min(remaining,1/120);step(slice);remaining-=slice;}}render();requestAnimationFrame(tick);}
collection();requestAnimationFrame(tick);

